export function palletPerceptionCsv(history){
 const columns=['received_at_ms','world_id','run_id','sim_s','state','reason','vision_fresh','tracked','signals_fresh','aligned','fully_inserted','last_full_before_support','sequence','capture_sim_s','age_s','confidence','plane_distance_m','hole_center_y_m','hole_center_z_m','yaw_rad','left_opening_width_m','right_opening_width_m','nominal_opening_height_m','depth_left_m','depth_right_m','depth_uncertainty_m','lateral_error_m','height_error_m','heel_range_fused'];
 const rows=[];for(const e of history){const f=e.frame,p=f?.pallet_perception;if(!p)continue;const vision=p.vision_fresh,geometry=p.signals_fresh&&(vision||p.tracked)&&!['unknown','supported','uneven_support'].includes(p.state);const keys=['confidence','plane_distance_m','hole_center_y_m','hole_center_z_m','yaw_rad','left_opening_width_m','right_opening_width_m'];rows.push([e.received_at_ms,f.source.world_id,f.source.run_id,f.sim_time_s,p.state,p.reason,p.vision_fresh,p.tracked,p.signals_fresh,p.aligned,p.fully_inserted,p.last_full_before_support,p.sequence,p.capture_sim_s,p.age_s,...keys.map(k=>vision?p[k]:null),p.nominal_opening_height_m,...['depth_left_m','depth_right_m','depth_uncertainty_m','lateral_error_m','height_error_m'].map(k=>geometry?p[k]:null),p.heel_range_fused].map(v=>v??'').join(','));}return {columns,rows,csv:columns.join(',')+'\n'+rows.join('\n')+'\n'};
}
